import { TokenRepository } from "@optee/user-server";
import { z } from "zod";

export const isHubspotCompatibleEnvironment = [
  "production",
  "preview",
].includes(process.env["VITE_ENV"] ?? "");

// Token cache in memory (per instance)
let cachedToken: { access_token: string; expiresAtMs: number } | null = null;

export const HubspotTokenProvider = {
  get: async () => {
    if (!isHubspotCompatibleEnvironment) {
      return;
    }

    const now = Date.now();

    // Use in-memory cache if still valid
    if (cachedToken && cachedToken.expiresAtMs > now) {
      return cachedToken.access_token;
    }

    // Fallback: try Supabase
    const data = await TokenRepository.get("hubspot");

    // No token found in Supabase ?
    if (!data) {
      // Let's get one and insert into Supabase
      const { access_token, expires_in } = await HubspotTokenProvider.refresh();

      const expiresInMs = expires_in * 1000;
      const expiresAtMs = now + expiresInMs;

      await TokenRepository.insert("hubspot", access_token, expiresAtMs);

      cachedToken = { access_token, expiresAtMs };

      return access_token;
    }

    // We have a token in Supabase, let's check if it's still valid
    if (new Date(data.expiresAt).getTime() > now) {
      cachedToken = {
        access_token: data.accessToken,
        expiresAtMs: new Date(data.expiresAt).getTime(),
      };
      return cachedToken.access_token;
    }

    // Token expired, let's refresh it
    // It's ok to refresh it even if we have a valid token in Supabase as it won't invalidate the previous one
    // Source: https://community.hubspot.com/t5/APIs-Integrations/Multiple-active-access-token/m-p/248202
    // "Refreshing a token with this endpoint will not automatically invalidate previous access tokens created with the same refresh token."
    const { access_token, expires_in } = await HubspotTokenProvider.refresh();

    const expiresInMs = expires_in * 1000;
    const expiresAtMs = now + expiresInMs;

    // Try to update Supabase (making sure we don't override a newer token)
    const updatedRow = await TokenRepository.updateSafely(
      "hubspot",
      access_token,
      expiresAtMs,
      data.expiresAt,
    );

    if (!updatedRow) {
      // If no rows were updated, it means the token was already refreshed by another instance
      // We can safely use the token generated by the other instance then
      const data = await TokenRepository.get("hubspot");

      if (!data) {
        throw new Error("Failed to update HubSpot token in Supabase");
      }

      // Update in-memory cache
      cachedToken = {
        access_token: data.accessToken,
        expiresAtMs: new Date(data.expiresAt).getTime(),
      };

      return cachedToken.access_token;
    }

    // Update in-memory cache
    cachedToken = { access_token, expiresAtMs };

    return access_token;
  },

  async refresh() {
    const hubspotClientId = process.env["HUBSPOT_CLIENT_ID"];
    const hubspotSecret = process.env["HUBSPOT_SECRET"];
    const hubspotRefreshToken = process.env["HUBSPOT_REFRESH_TOKEN"];

    if (!hubspotClientId || !hubspotSecret || !hubspotRefreshToken) {
      throw new Error("Missing HubSpot credentials in environment variables");
    }

    const refreshTokenRes = await fetch(
      "https://api.hubapi.com/oauth/v1/token",
      {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          grant_type: "refresh_token",
          client_id: hubspotClientId,
          client_secret: hubspotSecret,
          refresh_token: hubspotRefreshToken,
        }),
      },
    );

    if (!refreshTokenRes.ok) {
      const body = await refreshTokenRes.text();

      throw new Error(
        `Failed to refresh token: ${refreshTokenRes.status} ${body}`,
      );
    }

    const refreshTokenJson = await refreshTokenRes.json();

    const refreshTokenParsed = z
      .object({
        access_token: z.string(),
        expires_in: z.number(),
        refresh_token: z.string(),
      })
      .safeParse(refreshTokenJson);

    if (!refreshTokenParsed.success) {
      const error = refreshTokenParsed.error.format();

      throw new Error(
        `Failed to parse refresh token response: ${JSON.stringify(error)}`,
      );
    }

    return refreshTokenParsed.data;
  },
};
